import * as D from './domain.js';
import {localDateTime,zonedInput} from './dates.js';
import {load,getState,isDemo,toggleDemo,mutate,restore,backup,observe} from './store.js';
import {parseICS,importRecords} from './integrations.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal'),modalContent=document.querySelector('#modal-content');
let heatRange=90,heatMetric='events',questTab='active',filters={skill:'',source:'',status:'',query:'',from:'',to:'',type:''},selected=new Set(),reviewWeek='',busy=false,restoreData=null;
const quickLocks=new Set();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=u=>/^https?:\/\//i.test(u||'')?esc(u):'#';
const icons={dashboard:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',inbox:'<path d="M4 4h16l2 12v4H2v-4L4 4Z"/><path d="M2 15h6l2 3h4l2-3h6"/>',skills:'<path d="m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1 3-6Z"/>',quests:'<path d="M5 22V3m0 0c6-4 8 5 15 1v11c-7 4-9-5-15-1"/>',timeline:'<path d="M12 3v18M5 6h7m0 5h7M5 17h7"/><circle cx="4" cy="6" r="2"/><circle cx="20" cy="11" r="2"/><circle cx="4" cy="17" r="2"/>',achievements:'<path d="M8 3h8v7a4 4 0 0 1-8 0V3ZM8 5H3v3a5 5 0 0 0 5 5m8-8h5v3a5 5 0 0 1-5 5M12 14v6m-5 1h10"/>',review:'<path d="M4 20V10m5 10V4m6 16v-6m5 6V7"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',settings:'<path d="m9 3 1-2h4l1 2 3 2h3v5l2 2-2 2v5h-3l-3 2-1 2h-4l-1-2-3-2H3v-5l-2-2 2-2V5h3l3-2Z"/><circle cx="12" cy="12" r="3"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',bolt:'<path d="m13 2-8 12h7l-1 8 8-12h-7l1-8Z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M3 10h18M7 2v6m10-6v6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>'};
const icon=(name,size=17)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.skills}</svg>`;
const activeSkills=()=>getState().skills.filter(s=>!s.archived);
const skBy=id=>getState().skills.find(s=>s.id===id);
const localDay=()=>D.dayKey(new Date(),getState().profile.timezone);
const dateLabel=(date,opts={day:'numeric',month:'short'})=>new Intl.DateTimeFormat('es-ES',{...opts,timeZone:getState().profile.timezone}).format(new Date(date));
const dateHistorical=(date,precision='exact')=>{if(!date)return 'Fecha desconocida';if(precision==='year')return `≈ ${esc(date)}`;if(precision==='month')return '≈ '+new Intl.DateTimeFormat('es-ES',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(date+'-01T12:00:00Z'));return dateLabel(date.length===10?date+'T12:00:00Z':date);};
function datetimeInput(iso=new Date().toISOString()){return localDateTime(iso,getState().profile.timezone);}
const route=()=>location.hash.slice(1)||'/';
const names={'/':'Dashboard','/inbox':'Inbox','/skills':'Skills','/quests':'Quests','/timeline':'Timeline','/achievements':'Achievements','/review':'Weekly Review','/profile':'Profile','/settings':'Settings','/activities':'Historial'};
function toast(message,kind=''){const el=document.createElement('div');el.className='toast '+kind;el.textContent=message;const notifications=document.querySelector('#notifications');notifications.append(el);while(notifications.children.length>3)notifications.firstElementChild.remove();setTimeout(()=>el.remove(),kind==='achievement'?6500:4000);}
function notifyUnlocks(unlocks){const s=getState();for(const u of unlocks){const a=D.catalog(s).find(a=>a.code===u.code);toast(`🏆 Achievement unlocked · ${a?.name||u.code}`,'achievement');}}
async function change(fn,message){if(busy)return;busy=true;try{const {result,unlocks}=await mutate(fn);render();if(message)toast(message);notifyUnlocks(unlocks);return result;}catch(e){toast(e.message,'error');throw e;}finally{busy=false;}}
function empty(title,description,action='activity',label='Add Activity',symbol='✦'){return `<div class="empty"><div class="empty-symbol">${symbol}</div><strong>${esc(title)}</strong><p>${esc(description)}</p>${action?`<button class="btn btn-ghost btn-sm" data-action="${esc(action)}">${esc(label)}</button>`:''}</div>`;}
function heading(title,sub,action='',label=''){return `<div class="page-heading"><div><div class="eyebrow">YOUR PERSONAL JOURNEY</div><h1>${esc(title)}</h1><p class="subtitle">${esc(sub)}</p></div>${action?`<button class="btn btn-ghost" data-action="${esc(action)}">${icon('plus',14)} ${esc(label)}</button>`:''}</div>`;}
const quickDefaults={Fitness:['+1 entreno','Entrenamiento completado',40],Programming:['+1 sesión','Sesión de programación',40],Reading:['+1 lectura','Sesión de lectura',20],Business:['+1 sesión','Sesión de trabajo en mi negocio',40],Finance:['+1 sesión','Sesión de finanzas',20],Mathematics:['+1 práctica','Práctica de matemáticas',30],Networking:['+1 encuentro','Encuentro de networking',30],Writing:['+1 sesión','Sesión de escritura',20],Languages:['+1 práctica','Práctica de idiomas',20],Philosophy:['+1 sesión','Sesión de filosofía',20]};
function quickFor(sk){return quickDefaults[sk.name]||['+1 práctica',`Práctica de ${sk.name}`,20];}
function skillCard(sk){const p=D.progress(getState(),sk.id),[label,title,xp]=quickFor(sk),count=D.confirmed(getState()).filter(e=>e.skillId===sk.id&&D.dayKey(e.occurredAt,getState().profile.timezone)===localDay()).length;return `<article class="skill-card" style="--skill:${esc(sk.color)}"><div class="skill-top"><span class="skill-icon">${esc(sk.icon)}</span><div class="skill-label"><strong>${esc(sk.name)}</strong><small>Nivel ${p.level} · ${p.xp.toLocaleString('es')} XP</small></div></div><div class="bar" role="progressbar" aria-label="Progreso de ${esc(sk.name)}" aria-valuenow="${Math.round(p.fraction*100)}" aria-valuemin="0" aria-valuemax="100"><span style="width:${p.fraction*100}%"></span></div><button class="btn btn-primary one-tap" data-action="quick-log" data-skill="${esc(sk.id)}" ${quickLocks.has(sk.id)?'disabled':''}>${esc(label)} <small>+${xp} XP</small></button><p class="today-count" aria-live="polite">${count?`${count} ${count===1?'actividad registrada':'actividades registradas'} hoy`:'Tu primer paso de hoy'}</p><div class="card-links"><button data-action="activity" data-skill="${esc(sk.id)}" aria-label="Registrar otra actividad en ${esc(sk.name)}">Otra actividad</button><a href="#/skills/${esc(sk.id)}">Ver progreso →</a></div></article>`;}

function eventRow(e,full=false){const sk=skBy(e.skillId);const amount=e.status==='confirmed'&&e.xpMode==='award'?e.xp:0;return `<div class="activity-row" style="--skill:${esc(sk?.color||'#aaa')}"><div class="activity-icon">${esc(sk?.icon||'✦')}</div><div class="activity-copy"><strong>${esc(e.title)}</strong><small>${esc(sk?.name)} · ${dateLabel(e.occurredAt)} · ${esc(e.source)}${e.isHistorical?' · histórico':''}${full?' · '+esc(e.status):''}</small>${full&&e.description?`<p class="subtle" style="font-size:11px;margin-top:5px">${esc(e.description)}</p>`:''}${full&&e.evidence?`<a class="accent" style="font-size:10px" href="${safeUrl(e.evidence)}" target="_blank" rel="noopener noreferrer">Ver evidencia ↗</a>`:''}</div><span class="activity-xp">${e.status==='pending'?`~${e.xp} XP`:e.status==='rejected'?'Descartado':e.xpMode==='evidence_only'?'Sólo evidencia':`+${amount} XP`}</span></div>`;}
function heatmap(){const s=getState(),end=localDay(),start=D.shiftDay(end,-heatRange+1),weekstart=D.shiftDay(start,-((new Date(start+'T12:00Z').getUTCDay()+6)%7));const events=D.confirmed(s);const days=new Map();for(const e of events){const day=D.dayKey(e.occurredAt,s.profile.timezone);const cur=days.get(day)||{count:0,xp:0};cur.count++;cur.xp+=e.xpMode==='award'?e.xp:0;days.set(day,cur);}let boxes='',active=0,total=0;for(let d=weekstart;d<=end;d=D.shiftDay(d,1)){const val=days.get(d)||{count:0,xp:0};const value=heatMetric==='events'?val.count:val.xp;const intensity=heatMetric==='events'?Math.min(4,value):value===0?0:value<30?1:value<70?2:value<120?3:4;if(d>=start){if(val.count)active++;total+=val.count;}boxes+=`<button class="heatmap-day" data-intensity="${intensity}" data-action="heat-day" data-day="${d}" title="${d}: ${val.count} actividades · ${val.xp} XP" aria-label="${d}: ${val.count} actividades, ${val.xp} XP"></button>`;}const months=[];for(let d=start;d<=end;d=D.shiftDay(d,28))months.push(new Intl.DateTimeFormat('es',{month:'short'}).format(new Date(d+'T12:00Z')));return `<div class="panel"><div class="panel-heading"><h2>Activity graph</h2><div style="display:flex;gap:6px"><select class="select-small" id="heat-range" aria-label="Rango de actividad">${[[28,'4 semanas'],[90,'3 meses'],[365,'Último año']].map(([v,l])=>`<option value="${v}" ${v===heatRange?'selected':''}>${l}</option>`).join('')}</select><select class="select-small" id="heat-metric" aria-label="Intensidad de actividad"><option value="events" ${heatMetric==='events'?'selected':''}>Actividades</option><option value="xp" ${heatMetric==='xp'?'selected':''}>XP</option></select></div></div><div class="heatmap-container"><div class="heatmap-months">${[...new Set(months)].map(m=>`<span>${esc(m)}</span>`).join('')}</div><div class="heatmap">${boxes}</div></div><div class="heatmap-footer"><span>${active} días activos · ${total} actividades</span><span class="legend">Menos ${['#252830','#3e3654','#685287','#9273ba','#c1a0ed'].map(c=>`<span style="background:${c}"></span>`).join('')} Más</span></div></div>`;}
function questMini(q){const sk=skBy(q.skillId);return `<div class="quest-item" style="--skill:${esc(sk?.color||'#aaa')}"><div class="quest-line"><strong>${esc(q.name)}</strong><span class="gold" style="font-size:10px">+${q.rewardXp} XP</span></div><div class="bar"><span style="width:${Math.min(100,q.progress/q.target*100)}%"></span></div><div class="quest-meta"><span>${q.progress} / ${q.target} ${esc(q.unit)}</span><span>${q.deadline?dateLabel(q.deadline+'T12:00Z'):'Sin deadline'}</span></div></div>`;}
function dashboard(){const s=getState(),current=D.weeklySummary(s,D.weekStart(localDay())),previous=D.weeklySummary(s,D.shiftDay(D.weekStart(localDay()),-7)),streak=D.streaks(s),recent=D.confirmed(s).sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt)).slice(0,5),quests=s.quests.filter(q=>q.status==='active').slice(0,3),skills=activeSkills().sort((a,b)=>(a.name==='Fitness'?-1:b.name==='Fitness'?1:0));return heading(s.profile.name?`Tu próxima versión, ${s.profile.name.split(' ')[0]}.`:'Cada pequeño paso cuenta.','Termina una actividad. Toca +1. Sigue con tu día.')+`<div class="section-head"><h2>¿Qué has hecho hoy?</h2>${!s.profile.onboarded?'<button data-action="onboarding">Personalizar perfil</button>':''}</div><div class="skills-grid dashboard-skills">${skills.map(skillCard).join('')}</div><details class="other-capture"><summary>Registrar algo diferente o un hito</summary>${captureHome()}</details><div class="stats-grid">${stat('XP esta semana','+'+current.xp,'XP',current.xp>previous.xp?`↗ ${current.xp-previous.xp} XP más que la semana pasada`:`Semana pasada: ${previous.xp} XP`,'bolt',current.xp>previous.xp)}${stat('Racha actual',streak.current,'días',`Mejor racha: ${streak.best} días`,'bolt')}${stat('Actividades',D.confirmed(s).length,'',`${current.events} registradas esta semana`,'calendar')}${stat('Quests completadas',s.quests.filter(q=>q.status==='completed').length,'',`${s.quests.filter(q=>q.status==='active').length} aventuras en marcha`,'quests')}</div><div class="dashboard-bottom"><div><div class="section-head"><h2>Showing up is progress.</h2><span class="subtle" style="font-size:10px">Día a día</span></div>${heatmap()}<div class="section-head"><h2>Actividad reciente</h2><a href="#/activities">Ver historial ${icon('arrow',13)}</a></div><div class="panel list-panel">${recent.length?recent.map(e=>eventRow(e)).join(''):empty('Tu historia empieza aquí','Registra algo que hayas hecho hoy. No tiene que ser grande.')}</div></div><div><div class="section-head"><h2>Active quests</h2><a href="#/quests">Ver todas ${icon('arrow',13)}</a></div><div class="panel"><div class="panel-heading"><h2>El siguiente paso</h2><small>${quests.length} activas</small></div>${quests.length?quests.map(questMini).join(''):empty('Elige una pequeña aventura','Un objetivo concreto, una skill y tu propio ritmo.','quest','Crear quest','⚑')}</div><div class="quote-card"><p>“Progress, not perfection.”</p><small>Descansar también forma parte del camino.</small></div><div class="section-head"><h2>Tu memoria de progreso</h2></div><a href="#/timeline" class="panel" style="display:block"><span class="gold">${icon('timeline',22)}</span><h3 style="margin:10px 0 6px">Hay una historia detrás de tus skills.</h3><p class="subtle" style="font-size:11px">Conserva lo que ya has conseguido, sin reconstruir cada día.</p><span class="accent" style="display:block;margin-top:15px;font-size:11px">Explorar timeline →</span></a></div></div>`;}
function captureHome(){return `<section class="capture-home"><div class="eyebrow">UN PEQUEÑO PASO, AHORA</div><h2>¿Qué has hecho o conseguido?</h2><form data-form="quick-start" class="capture-start"><label class="sr-only" for="quick-title">Qué has hecho o conseguido</label><input id="quick-title" name="title" placeholder="He terminado mi proyecto, he ido al gimnasio…" maxlength="180" required autocomplete="off"><button class="btn btn-primary" type="submit">Continuar ${icon('arrow',16)}</button></form><div class="capture-shortcuts"><span>O empieza por una habilidad:</span>${activeSkills().map(sk=>`<button class="skill-chip" data-action="activity" data-skill="${esc(sk.id)}">${esc(sk.icon)} ${esc(sk.name)} <span>+</span></button>`).join('')}</div><button class="milestone-shortcut" data-action="milestone">${icon('achievements',18)} He conseguido un hito <span>Primer cliente, proyecto terminado, carrera… →</span></button></section>`;}
const suggestions={Fitness:[['He ido al gimnasio',40],['He salido a correr',40],['He caminado 30 minutos',20]],Programming:[['He trabajado en mi proyecto',40],['He practicado programación',20],['He hecho 3 commits',15]],Reading:[['He leído 30 minutos',20],['He terminado un capítulo',20]],Business:[['He trabajado en mi negocio',40],['He tenido una reunión con un cliente',30]],Writing:[['He escrito durante 30 minutos',20]],Languages:[['He practicado un idioma',20]],Mathematics:[['He resuelto ejercicios',30]]};
function captureSuggestions(skillId){return (suggestions[skBy(skillId)?.name]||[['He practicado 30 minutos',20],['He trabajado durante una hora',40]]).map(([title,xp])=>`<button type="button" class="suggestion" data-action="capture-preset" data-title="${esc(title)}" data-xp="${xp}">${esc(title)} <small>+${xp} XP</small></button>`).join('');}
function stat(title,value,unit,note,symbol,good=false){return `<div class="stat"><div class="stat-top"><span>${esc(title)}</span>${icon(symbol,16)}</div><div class="stat-value">${esc(value)}<span>${esc(unit)}</span></div><div class="stat-note ${good?'good':''}">${esc(note)}</div></div>`;}
function skillsView(){return heading('Your skills','Cada habilidad tiene su propio camino. Tú decides en qué avanzar.','skill','Nueva skill')+`<div class="skills-grid">${activeSkills().map(skillCard).join('')}</div><p class="view-description" style="margin-top:25px">Los niveles representan práctica acumulada. No son una nota sobre tu valor ni una comparación con otros.</p>`;}
function skillDetail(id){const s=getState(),sk=skBy(id);if(!sk)return empty('Skill no encontrada','Vuelve a la lista de habilidades.',null);const p=D.progress(s,id),events=D.confirmed(s).filter(e=>e.skillId===id).sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt)),ledger=s.ledger.filter(x=>x.skillId===id).sort((a,b)=>a.effectiveAt.localeCompare(b.effectiveAt));let running=0;const amounts=ledger.map(x=>(running+=x.amount));const points=amounts.length?[0,...amounts]:[0,0];const max=Math.max(...points,1),coords=points.map((v,i)=>`${20+i/(points.length-1)*560},${145-v/max*125}`).join(' ');const related=s.quests.filter(q=>q.skillId===id);return `<div class="page-heading"><div class="skill-detail-header" style="--skill:${esc(sk.color)}"><span class="skill-icon">${esc(sk.icon)}</span><div><div class="eyebrow">SKILL PROGRESSION</div><h1>${esc(sk.name)}</h1><p class="skill-description">${esc(sk.description)}</p></div></div><button class="btn btn-ghost" data-action="skill" data-id="${esc(id)}">Editar skill</button></div><div class="two-col"><div><div class="panel" style="--skill:${esc(sk.color)}"><span class="pill">${p.level===100?'MAX LEVEL':'LEVEL '+p.level}</span><div class="skill-detail-level">${p.xp.toLocaleString('es')} <small>XP acumulada</small></div><div class="bar"><span style="width:${p.fraction*100}%"></span></div><p class="skill-meta">${p.level===100?'Has alcanzado Level 100. Puedes seguir acumulando XP.':`${p.remaining.toLocaleString('es')} XP hasta Level ${p.level+1}`}</p><h2>Evolución</h2><svg class="graph" viewBox="0 0 600 170" role="img" aria-label="Evolución de XP: ${p.xp} XP total"><path d="M20 145H580M20 82H580M20 20H580" stroke="#282b35"/><polyline points="${coords}" fill="none" stroke="${esc(sk.color)}" stroke-width="2.5"/><polyline points="20,145 ${coords} 580,145" fill="${esc(sk.color)}" opacity=".07"/></svg><div class="graph-labels"><span>${ledger.length?dateLabel(ledger[0].effectiveAt):'Punto de partida'}</span><span>Hoy</span></div></div><div class="section-head"><h2>Actividades recientes</h2><button data-action="activity" data-skill="${esc(id)}">+ Registrar</button></div><div class="panel list-panel">${events.length?events.slice(0,12).map(e=>eventRow(e,true)).join(''):empty('Práctica pendiente','Tu próximo paso es la primera actividad.','activity')}</div><div class="section-head"><h2>XP ledger</h2></div><div class="panel table-scroll"><table class="ledger-table"><thead><tr><th>Fecha</th><th>Motivo</th><th>Tipo</th><th>XP</th></tr></thead><tbody>${ledger.slice().reverse().map(x=>`<tr><td>${dateLabel(x.effectiveAt)}</td><td>${esc(x.reason)}</td><td>${esc(x.type)}</td><td class="accent">+${x.amount}</td></tr>`).join('')}</tbody></table>${ledger.length?'':`<p class="subtle" style="padding:20px 0;font-size:12px">Toda concesión de XP aparecerá aquí con su motivo.</p>`}</div></div><div><div class="panel"><h2>Quests relacionadas</h2>${related.length?related.map(questMini).join(''):empty('Sin quests todavía','Define un objetivo para esta habilidad.','quest','Crear quest','⚑')}</div><div class="section-head"><h2>Logros de esta skill</h2></div>${D.catalog(s).filter(a=>a.skillId===id).map(a=>achievementCard(a)).join('')}${!ledger.length?`<div class="quote-card"><h3>Tu punto de partida</h3><p style="margin-top:8px;font-size:12px">¿Ya llevas tiempo practicando? Define un nivel inicial aproximado.</p><button class="btn btn-sm" style="margin-top:14px" data-action="baseline" data-id="${esc(id)}">Añadir baseline</button></div>`:''}</div></div>`;}
function filterBar(mode='events'){return `<div class="filters"><input id="filter-query" type="search" value="${esc(filters.query)}" placeholder="Buscar en tu historia…" aria-label="Buscar actividades"><select id="filter-skill" aria-label="Filtrar por skill"><option value="">Todas las skills</option>${activeSkills().map(sk=>`<option value="${esc(sk.id)}" ${filters.skill===sk.id?'selected':''}>${esc(sk.name)}</option>`).join('')}</select>${mode==='events'?`<select id="filter-source" aria-label="Filtrar por origen"><option value="">Todos los orígenes</option>${['manual','github','calendar'].map(x=>`<option ${filters.source===x?'selected':''}>${x}</option>`).join('')}</select><select id="filter-status" aria-label="Filtrar por estado"><option value="">Todos los estados</option>${['confirmed','pending','rejected'].map(x=>`<option ${filters.status===x?'selected':''}>${x}</option>`).join('')}</select>`:`<select id="filter-type" aria-label="Filtrar por tipo"><option value="">Todos los tipos</option>${[['activity','Actividades'],['level','Level ups'],['quest','Quests'],['achievement','Achievements'],['milestone','Milestones']].map(([v,l])=>`<option value="${v}" ${filters.type===v?'selected':''}>${l}</option>`).join('')}</select>`}<input id="filter-from" type="date" value="${esc(filters.from)}" aria-label="Desde"><input id="filter-to" type="date" value="${esc(filters.to)}" aria-label="Hasta"></div>`;}
function activitiesView(){const s=getState();const list=s.events.filter(e=>(!filters.skill||e.skillId===filters.skill)&&(!filters.source||e.source===filters.source)&&(!filters.status||e.status===filters.status)&&(!filters.query||(e.title+' '+e.description).toLowerCase().includes(filters.query.toLowerCase()))&&(!filters.from||D.dayKey(e.occurredAt,s.profile.timezone)>=filters.from)&&(!filters.to||D.dayKey(e.occurredAt,s.profile.timezone)<=filters.to)).sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt));return heading('Your activity history','Cada acción es una parte de tu historia.')+filterBar()+`<p class="subtle" style="font-size:11px;margin-bottom:15px">${list.length} actividades</p><div class="panel list-panel">${list.length?list.map(e=>eventRow(e,true)).join(''):empty('Sin actividades en este rango','Prueba otros filtros o registra tu primera actividad.')}</div>`;}
function questsView(){const list=getState().quests.filter(q=>q.status===questTab);return heading('Your quests','Objetivos concretos. Pequeñas aventuras con un final claro.','quest','Nueva quest')+`<div class="toolbar"><div class="tab-group">${[['active','Activas'],['completed','Completadas'],['abandoned','Abandonadas']].map(([v,l])=>`<button class="tab ${questTab===v?'active':''}" data-action="quest-tab" data-tab="${v}">${l}</button>`).join('')}</div><span class="subtle" style="font-size:11px">Las quests no penalizan por descansar.</span></div><div class="grid-2">${list.map(q=>{const sk=skBy(q.skillId);return `<div class="quest-card" style="--skill:${esc(sk?.color||'#aaa')}"><div class="quest-card-head"><span class="pill">${esc(sk?.icon)} ${esc(sk?.name)}</span><span class="gold" style="font-size:12px">+${q.rewardXp} XP</span></div><h2 style="margin-top:20px">${esc(q.name)}</h2><p>${esc(q.description||'Un paso más en tu camino.')}</p><div class="bar"><span style="width:${Math.min(100,q.progress/q.target*100)}%"></span></div><div class="quest-meta"><span>${q.progress} / ${q.target} ${esc(q.unit)}</span><span>${q.deadline?`${q.deadline<localDay()&&q.status==='active'?'Vencida · ':''}${dateLabel(q.deadline+'T12:00Z')}`:'Sin deadline'}</span></div>${q.status==='active'?`<form class="quest-controls" data-form="quest-progress" data-id="${esc(q.id)}"><input type="number" name="progress" value="${q.progress}" min="0" max="1000000" step="any" aria-label="Progreso de ${esc(q.name)}" required><button class="btn btn-sm" type="submit">Actualizar</button><button class="btn btn-ghost btn-sm" type="button" data-action="quest-abandon" data-id="${esc(q.id)}">Abandonar</button></form>`:`<p class="quest-status">${q.status==='completed'?'✓ Completada · '+dateLabel(q.completedAt):'Abandonada · tu progreso en la skill se conserva'}</p>`}</div>`;}).join('')}</div>${list.length?'':empty('Una nueva aventura te espera','No hace falta un gran objetivo. Puedes empezar con tres entrenamientos o diez páginas.','quest','Crear quest','⚑')}`;}
function achievementCard(a){const u=getState().unlocks.find(u=>u.code===a.code);return `<div class="achievement-card ${u?'unlocked':'locked'}" style="margin-bottom:12px"><div class="achievement-icon">${esc(a.icon)}</div><div><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p><small>${u?`${u.isHistorical?'Histórico · ':''}${dateHistorical(u.unlockedAt,u.precision)}`:'Por desbloquear'}</small></div></div>`;}
function achievementsView(){const s=getState(),all=D.catalog(s),unlocked=all.filter(a=>s.unlocks.some(u=>u.code===a.code)),locked=all.filter(a=>!s.unlocks.some(u=>u.code===a.code));return heading('Your achievements','La práctica suma XP. Los resultados merecen un lugar en tu historia.')+`<p class="view-description">${unlocked.length} logros desbloqueados · Cada hito guarda su fecha real, también los anteriores a HT.</p><div class="achievement-grid">${[...unlocked,...locked].map(achievementCard).join('')}</div>`;}
function timelineView(){const s=getState(),list=D.timeline(s).filter(r=>(!filters.skill||r.skillIds.includes(filters.skill))&&(!filters.type||r.type===filters.type)&&(!filters.query||(r.title+' '+(r.description||'')).toLowerCase().includes(filters.query.toLowerCase()))&&(!filters.from||(r.date&&r.date.slice(0,10)>=filters.from))&&(!filters.to||(r.date&&r.date.slice(0,10)<=filters.to)));let month='',rows='';for(const r of list){const m=r.date?r.date.slice(0,7):'unknown';if(m!==month){month=m;rows+=`<div class="timeline-month">${m==='unknown'?'Fecha desconocida':r.precision==='year'?esc(r.date):new Intl.DateTimeFormat('es',{month:'long',year:'numeric'}).format(new Date(m+'-01T12:00Z'))}</div>`;}rows+=`<div class="timeline-row"><span class="timeline-dot"></span><span class="date">${dateHistorical(r.date,r.precision)}</span><div style="flex:1"><h3 class="${r.type==='achievement'?'gold':r.type==='level'?'accent':''}">${r.type==='achievement'?'🏆 ':r.type==='quest'?'⚑ ':''}${esc(r.title)}</h3>${r.description?`<p>${esc(r.description)}</p>`:''}<span class="pill">${esc(r.type)}${r.isHistorical?' · histórico':''}${r.xp?' · +'+r.xp+' XP':''}</span></div></div>`;}return heading('Your timeline','La historia que estás construyendo, paso a paso.','milestone','Añadir milestone')+filterBar('timeline')+`<div class="panel">${rows||empty('Tu timeline aún está por escribir','Empieza con una actividad o conserva un hito importante del pasado.','milestone','Añadir milestone','◇')}</div>`;}
function weeklyView(){const s=getState();if(!reviewWeek)reviewWeek=D.weekStart(localDay());const summary=D.weeklySummary(s,reviewWeek),prev=D.weeklySummary(s,D.shiftDay(reviewWeek,-7)),reflection=s.reflections[reviewWeek]||{},delta=summary.xp-prev.xp;return heading('Pause. Reflect. Grow.','Una semana no define tu camino. Una reflexión puede ayudarte a elegir el siguiente paso.')+`<div class="toolbar"><div style="display:flex;gap:8px;align-items:center"><button class="btn btn-ghost btn-sm" data-action="review-prev" aria-label="Semana anterior">←</button><span style="font-size:12px">${dateLabel(reviewWeek+'T12:00Z')} — ${dateLabel(D.shiftDay(reviewWeek,6)+'T12:00Z',{day:'numeric',month:'short',year:'numeric'})}</span><button class="btn btn-ghost btn-sm" data-action="review-next" ${reviewWeek>=D.weekStart(localDay())?'disabled':''} aria-label="Semana siguiente">→</button></div><span class="pill">${reviewWeek===D.weekStart(localDay())?'Semana en curso':'Revisión semanal'}</span></div><div class="stats-grid">${stat('XP de la semana',summary.xp,'XP',`${delta>=0?'+':''}${delta} XP frente a la anterior`,'bolt')}${stat('Actividades',summary.events,'',`${summary.historical} históricas, contabilizadas aparte`,'calendar')}${stat('Quests',summary.quests.length,'',`${summary.questXp} XP de recompensas`,'quests')}${stat('Achievements',summary.unlocks.length,'','Hitos desbloqueados esta semana','achievements')}</div><div class="two-col"><form class="panel review-card" data-form="reflection"><h2>Tu reflexión</h2><p class="subtle" style="font-size:12px;margin-top:7px">Un espacio para pensar, sin convertirlo todo en métricas.</p><label for="went-well">What went well?</label><textarea id="went-well" name="wentWell" placeholder="¿Qué quieres repetir?">${esc(reflection.wentWell)}</textarea><label for="went-wrong">What went wrong?</label><textarea id="went-wrong" name="wentWrong" placeholder="¿Qué te ha costado?">${esc(reflection.wentWrong)}</textarea><label for="next-focus">What should I focus on next week?</label><textarea id="next-focus" name="nextFocus" placeholder="Un siguiente paso concreto…">${esc(reflection.nextFocus)}</textarea><button class="btn btn-primary" type="submit">Guardar reflexión</button>${reflection.savedAt?`<small class="subtle" style="display:block;margin-top:12px">Guardada · ${dateLabel(reflection.savedAt)}</small>`:''}</form><div><div class="panel"><h2>Skills más trabajadas</h2>${summary.perSkill.length?summary.perSkill.map(sk=>`<div class="activity-row" style="--skill:${esc(sk.color)}"><span class="activity-icon">${esc(sk.icon)}</span><div class="activity-copy"><strong>${esc(sk.name)}</strong></div><span class="activity-xp">+${sk.xp} XP</span></div>`).join(''):empty('Sin práctica esta semana','Tu progreso anterior sigue intacto.',null)}<p class="subtle" style="font-size:10px;margin-top:15px">${summary.activityXp} XP de actividades · ${summary.questXp} XP de quests. Baselines excluidos.</p></div><div class="section-head"><h2>Quests completadas</h2></div><div class="panel">${summary.quests.length?summary.quests.map(questMini).join(''):empty('Una semana también puede ser de descanso','Tus niveles no bajan por parar.',null,'','☾')}</div></div></div>`;}
function inboxView(){const s=getState(),pending=s.events.filter(e=>e.status==='pending').sort((a,b)=>b.occurredAt.localeCompare(a.occurredAt));let group='',html='';for(const e of pending){const day=D.dayKey(e.occurredAt,s.profile.timezone);if(day!==group){group=day;html+=`<div class="inbox-group">${dateLabel(e.occurredAt,{day:'numeric',month:'long',year:'numeric'})}</div>`;}const sk=skBy(e.skillId);html+=`<div class="inbox-card"><div class="inbox-top"><input class="checkbox inbox-check" type="checkbox" value="${esc(e.id)}" ${selected.has(e.id)?'checked':''} aria-label="Seleccionar ${esc(e.title)}"><div style="flex:1"><span class="pill">${esc(e.source)}${e.isHistorical?' · histórico':''}</span><h3 style="margin-top:9px">${esc(e.title)}</h3><p>${esc(sk?.name)} · <span class="accent">${e.xpMode==='evidence_only'?'Sólo evidencia · +0 XP adicional':`Propuesta +${e.xp} XP`}</span></p></div></div>${e.xpMode==='evidence_only'?`<p>Esta fecha está incluida en el baseline de la skill. Se conserva como evidencia sin duplicar XP.</p>`:''}${e.evidence?`<a href="${safeUrl(e.evidence)}" rel="noopener noreferrer" target="_blank" class="accent" style="font-size:11px;display:inline-block;margin-top:12px">Ver evidencia ↗</a>`:''}<div class="actions"><button class="btn btn-primary btn-sm" data-action="event-confirm" data-id="${esc(e.id)}">${icon('check',13)} Confirm</button><button class="btn btn-ghost btn-sm" data-action="event-edit" data-id="${esc(e.id)}">Edit</button><button class="btn btn-ghost btn-sm" data-action="event-reject" data-id="${esc(e.id)}">Reject</button></div></div>`;}return heading('Your XP inbox','La actividad externa propone. Tú decides qué cuenta.')+`<div class="toolbar"><span class="subtle" style="font-size:12px">${pending.length} actividades pendientes</span><a class="btn btn-ghost btn-sm" href="#/settings">Importar actividad</a></div>${pending.length?`<div class="toolbar"><button class="btn btn-ghost btn-sm" data-action="select-all">${selected.size===pending.length?'Deseleccionar':'Seleccionar'} todas</button><div style="display:flex;gap:7px"><button class="btn btn-primary btn-sm" data-action="bulk-confirm" ${selected.size?'':'disabled'}>Confirmar ${selected.size} seleccionadas</button><button class="btn btn-ghost btn-sm" data-action="bulk-reject" ${selected.size?'':'disabled'}>Descartar</button></div></div>`:''}${html||empty('Todo al día','Conecta actividad pública de GitHub o importa un calendario .ics. La XP sólo llega después de tu confirmación.',null,'','▱')}`;}
function profileView(){const s=getState(),st=D.streaks(s);return heading('Your character sheet','No hay un nivel de vida. Hay muchas formas de crecer.','profile-edit','Editar perfil')+`<div class="profile-hero"><div class="profile-avatar">${esc(s.profile.avatar)}</div><h1>${esc(s.profile.name||'Tu personaje')}</h1><p>Una historia en construcción.</p><span class="pill">En esta aventura desde ${dateLabel(s.profile.createdAt,{month:'long',year:'numeric'})}</span></div><div class="stats-grid" style="margin-top:22px">${stat('Actividades',D.confirmed(s).length,'','Acciones confirmadas','calendar')}${stat('Achievements',s.unlocks.length,'','Resultados y milestones','achievements')}${stat('Racha actual',st.current,'días',`Mejor racha: ${st.best} días`,'bolt')}${stat('Skills',activeSkills().length,'','Cada una, su propio progreso','skills')}</div><div class="section-head"><h2>Skills & levels</h2><a href="#/skills">Explorar skills →</a></div><div class="skills-grid">${activeSkills().map(skillCard).join('')}</div><div class="section-head"><h2>Achievements destacados</h2><a href="#/achievements">Ver todos →</a></div><div class="achievement-grid">${D.catalog(s).filter(a=>s.unlocks.some(u=>u.code===a.code)).slice(0,6).map(achievementCard).join('')}</div>${s.unlocks.length?'':empty('Tus hitos tendrán un lugar aquí','También puedes añadir resultados anteriores a utilizar HT.','milestone','Añadir milestone','◇')}`;}
function settingsView(){const s=getState();return heading('Make it yours.','Tu perfil, tus fuentes de actividad y el control de tus datos.')+`<div class="notice">Tus datos se guardan en este navegador. Exporta una copia para conservarlos o llevarlos a otro dispositivo. No hay cuenta ni sincronización en la nube en esta primera versión.</div><div class="grid-2"><form class="panel settings-panel" data-form="profile"><h2>Tu perfil</h2><label for="profile-name">Nombre</label><input id="profile-name" name="name" value="${esc(s.profile.name)}" maxlength="60" required><label for="profile-avatar">Símbolo de personaje</label><input id="profile-avatar" name="avatar" value="${esc(s.profile.avatar)}" maxlength="12" required><label for="profile-timezone">Zona horaria</label><select id="profile-timezone" name="timezone">${timezones().map(tz=>`<option ${s.profile.timezone===tz?'selected':''}>${esc(tz)}</option>`).join('')}</select><p style="margin-top:12px">Las rachas y las semanas siguen esta zona horaria.</p><button class="btn btn-primary" type="submit">Guardar perfil</button></form><div class="panel settings-panel"><h2>Tu historia antes de HT</h2><p>Un nivel inicial aproximado y tus hitos importantes. No hace falta reconstruir cientos de días.</p><button class="btn btn-ghost" data-action="baseline">Añadir baseline a una skill</button><br><button class="btn btn-ghost" data-action="milestone">Añadir milestone histórico</button><p style="margin-top:22px">La fecha de corte del baseline evita duplicar XP al importar el pasado.</p><a href="#/timeline" class="accent" style="font-size:12px">Ver tu timeline →</a></div><form class="panel settings-panel" data-form="github"><h2>GitHub · actividad pública</h2><p>Importa commits, pull requests y repositorios públicos. Todos entran pendientes al Inbox. Sin OAuth ni acceso a repositorios privados en esta versión.</p><label for="github-user">Usuario de GitHub</label><input id="github-user" name="username" placeholder="Guamusti" value="${esc(s.integrations.github)}" pattern="[A-Za-z0-9-]{1,39}" required><label for="github-since">Importar desde</label><input id="github-since" name="since" type="date" value="${D.shiftDay(localDay(),-30)}" max="${localDay()}" required><label for="github-skill">Skill para la actividad</label><select id="github-skill" name="skillId">${skillOptions()}</select><button class="btn btn-primary" type="submit" ${busy?'disabled':''}>Importar a Inbox</button><p style="margin-top:12px;font-size:10px">Alcance limitado a 12 repositorios recientes y 100 commits por repositorio. El resultado indica omisiones y límites. Puedes repetir la importación sin duplicar evidencias.</p></form><div class="panel settings-panel"><h2>Calendar · archivo .ics</h2><p>Exporta un calendario desde Google Calendar, Outlook o Apple Calendar e impórtalo. Se revisan sólo eventos pasados; un calendario no demuestra asistencia.</p><label for="calendar-skill">Skill sugerida</label><select id="calendar-skill">${skillOptions(activeSkills().find(sk=>sk.name==='Mathematics')?.id)}</select><label for="calendar-file">Archivo de calendario</label><input id="calendar-file" type="file" accept=".ics,text/calendar"><p style="margin-top:12px;font-size:10px">No hay sincronización OAuth. Las reglas de recurrencia no se expanden: se importan las instancias explícitas del archivo y se informa de las omitidas.</p></div><div class="panel settings-panel"><h2>Backup & portability</h2><p>La copia incluye actividades, ledger, quests, logros, milestones y reflexiones. Guarda el JSON en un lugar seguro.</p><button class="btn btn-primary" data-action="export">Exportar mis datos</button><label for="restore-file">Restaurar desde un backup de HT</label><input id="restore-file" type="file" accept=".json,application/json"><p style="margin-top:12px;font-size:10px">Podrás revisar la copia antes de reemplazar tu perfil. Se descarga una copia del perfil actual antes de restaurar.</p></div><div class="panel settings-panel"><h2>Explore the journey</h2><p>Prueba la demo en un perfil independiente. Las acciones de la demo no modifican tu historia real.</p><button class="btn btn-ghost" data-action="demo">${isDemo()?'Volver a mi perfil':'Abrir demo'}</button><p style="margin-top:20px">HT 0.1 · Curva de niveles v1<br>XP sin decay · Sin puntuación global</p><a class="accent" style="font-size:11px" href="/docs/first-approach.md">Propuesta de arquitectura →</a></div></div>`;}
function timezones(){return [...new Set([getState().profile.timezone,'Europe/Madrid','Europe/London','UTC','America/Lima','America/New_York','Asia/Dubai'])];}
function render(){const s=getState();if(!s)return;const r=route(),name=names[r]||(r.startsWith('/skills/')?'Skill detail':'Dashboard'),pending=s.events.filter(e=>e.status==='pending').length;let body;switch(r){case '/skills':body=skillsView();break;case '/quests':body=questsView();break;case '/timeline':body=timelineView();break;case '/achievements':body=achievementsView();break;case '/review':body=weeklyView();break;case '/profile':body=profileView();break;case '/settings':body=settingsView();break;case '/activities':body=activitiesView();break;case '/inbox':body=inboxView();break;default:body=r.startsWith('/skills/')?skillDetail(r.split('/')[2]):dashboard();}const nav=[['/','dashboard','Dashboard'],['/inbox','inbox','Inbox'],['/skills','skills','Skills'],['/quests','quests','Quests'],['/timeline','timeline','Timeline'],['/achievements','achievements','Achievements'],['/review','review','Weekly Review'],['/profile','profile','Profile'],['/settings','settings','Settings']];app.innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand" href="#/"><span class="brand-symbol">✦</span><span><strong>HT</strong><small>PERSONAL PROGRESS</small></span></a><div class="nav-heading">YOUR JOURNEY</div><nav>${nav.map(([url,symbol,label])=>`<a class="nav-link ${url===r||(url==='/skills'&&r.startsWith('/skills/'))?'active':''}" href="#${url}" ${url===r?'aria-current="page"':''}>${icon(symbol)}<span>${label}</span>${url==='/inbox'&&pending?`<span class="count">${pending}</span>`:''}</a>`).join('')}</nav><div class="sidebar-footer"><div class="local-status"><span class="dot"></span>Guardado en este navegador</div><a class="user-mini" href="#/profile"><span class="avatar">${esc(s.profile.avatar)}</span><span><strong>${esc(s.profile.name||'Tu personaje')}</strong><small>${isDemo()?'Perfil demo':'Una historia en construcción'}</small></span></a></div></aside><main class="main">${isDemo()?`<div class="demo-banner">DEMO · Datos de ejemplo en un perfil independiente.<button data-action="demo">Volver a mi perfil</button></div>`:''}<header class="topbar"><div class="crumb">My journey <span style="margin:0 10px;color:#434853">/</span> <strong>${esc(name)}</strong></div><a class="mobile-brand" href="#/"><span>✦</span> HT</a><div class="topbar-right"><span class="subtle-date">${dateLabel(new Date(),{weekday:'short',day:'numeric',month:'long'})}</span><button class="btn btn-ghost btn-sm demo-trigger" data-action="demo">${isDemo()?'Mi perfil':'Explore demo'}</button><button class="icon-btn mobile-more" data-action="more" aria-label="Más vistas">${icon('settings',19)}</button><button class="btn btn-primary" data-action="activity">${icon('plus',14)} Registrar</button></div></header><div class="page-in">${body}</div><footer class="footer-note"><span>Small steps. Real progress.</span><span>No XP decay. No life score. Just your journey.</span></footer></main></div>`;}
const skillOptions=(value)=>activeSkills().map(sk=>`<option value="${esc(sk.id)}" ${value===sk.id?'selected':''}>${esc(sk.icon)} ${esc(sk.name)}</option>`).join('');
function field(label,name,type='text',value='',extra=''){return `<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='datetime-local'?'step="0.001"':''} ${extra}></div>`;}
function selectField(label,name,options){return `<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}">${options}</select></div>`;}
function textarea(label,name,value=''){return `<div class="field"><label for="f-${name}">${esc(label)}</label><textarea id="f-${name}" name="${name}" maxlength="3000">${esc(value)}</textarea></div>`;}
function openForm(title,sub,type,content,id='',submit='Guardar'){modalContent.innerHTML=`<div class="modal-header"><div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div><button class="icon-btn" data-action="close" aria-label="Cerrar">${icon('close',20)}</button></div><form class="modal-body" data-form="${type}" data-id="${esc(id)}">${content}<p class="form-error" role="alert"></p><div class="modal-footer"><button type="button" class="btn btn-ghost" data-action="close">Cancelar</button><button type="submit" class="btn btn-primary">${esc(submit)}</button></div></form>`;if(!modal.open)modal.showModal();}
function activityForm(skillId,title=''){const chosen=skillId||activeSkills()[0]?.id;openForm('Registra un paso.','Una actividad de hoy. Ajusta los detalles sólo si lo necesitas.','activity',`<div class="capture-mode"><span class="selected">He practicado</span><button type="button" data-action="capture-milestone">He conseguido un hito →</button></div>`+field('¿Qué has hecho?','title','text',title,'placeholder="Escribe una actividad o elige una sugerencia" maxlength="180" required')+selectField('Habilidad','skillId',skillOptions(chosen))+`<div class="capture-suggestions">${captureSuggestions(chosen)}</div><div class="effort-picker"><span>Práctica / esfuerzo</span>${[[10,'Pequeño'],[20,'Normal'],[40,'Intenso'],[60,'Extra']].map(([xp,label])=>`<button type="button" class="${xp===40?'selected':''}" data-action="xp-preset" data-xp="${xp}">${label}<small>+${xp} XP</small></button>`).join('')}</div><details class="capture-details"><summary>Fecha, nota y más opciones</summary><div class="field-row">${field('XP (editable)','xp','number','40','min="0" max="1000000" step="1" required')}${field('Fecha y hora (vacío = ahora)','occurredAt','datetime-local','')}</div>`+textarea('Nota opcional','description')+field('Evidencia opcional (URL)','evidence','url','','placeholder="https://…"')+selectField('Quest relacionada (opcional)','questId','<option value="">Ninguna</option>'+getState().quests.filter(q=>q.status==='active').map(q=>`<option value="${esc(q.id)}">${esc(q.name)}</option>`).join(''))+field('Progreso aportado a la quest','questDelta','number','1','min="0.01" max="1000000" step="any"')+`<label class="check-label"><input type="checkbox" name="isHistorical"> Actividad histórica</label></details><p class="capture-note">Hoy · Se guarda directamente en tu historia.</p>`,'','Guardar actividad');modal.querySelector('[name="title"]').focus();}
function skillForm(id){const sk=skBy(id);openForm(sk?'Edit skill':'Una nueva habilidad.','Cada skill tiene su propio nivel y progreso.','skill',field('Nombre','name','text',sk?.name||'','maxlength="60" required')+`<div class="field-row">${field('Icono o símbolo','icon','text',sk?.icon||'✦','maxlength="12" required')}${field('Color','color','color',sk?.color||'#9b88ff')}</div>`+textarea('Descripción','description',sk?.description||''),id||'');}
function baselineForm(id){const eligible=activeSkills().filter(sk=>!getState().ledger.some(x=>x.skillId===sk.id));if(!eligible.length){toast('Todas tus skills ya tienen progreso. Crea una nueva skill para definir su punto de partida.');return;}openForm('Tu punto de partida.','Nivel aproximado antes de utilizar HT. Se registra en el ledger.','baseline',selectField('Skill','skillId',eligible.map(sk=>`<option value="${esc(sk.id)}" ${sk.id===id?'selected':''}>${esc(sk.name)}</option>`).join(''))+field('Nivel inicial','level','number','1','min="1" max="100" required')+field('Fecha de corte histórica','cutoff','datetime-local',datetimeInput(),'required')+`<p class="subtle" style="font-size:11px;margin-top:16px">La actividad importada anterior al corte se conservará como evidencia sin añadir XP que ya representa el baseline. El baseline sólo se fija una vez.</p>`);}
function questForm(){openForm('Choose your next quest.','Un objetivo concreto y una recompensa por completarlo.','quest',field('Nombre','name','text','','placeholder="Ir al gimnasio 3 veces" maxlength="180" required')+selectField('Skill','skillId',skillOptions())+textarea('Descripción opcional','description')+`<div class="field-row">${field('Objetivo','target','number','3','min="0.01" max="1000000" step="any" required')}${field('Unidad','unit','text','sesiones','maxlength="40" required')}</div><div class="field-row">${field('Recompensa XP','rewardXp','number','80','min="0" max="1000000" step="1" required')}${field('Deadline opcional','deadline','date','','min="'+localDay()+'"')}</div>`,'','Crear quest');}
function milestoneForm(title='',skillId=''){openForm('Guarda lo que has conseguido.','Un resultado importante merece un lugar en tu historia.','milestone',field('Nombre del hito','title','text',title,'placeholder="Mi primer cliente de pago" maxlength="180" required')+`<details class="capture-details"><summary>Fecha, habilidades y más detalles</summary>`+textarea('Historia opcional','description')+selectField('Tipo de milestone','type',[['personal','Personal'],['first_client','Primer cliente de pago'],['first_company','Primera empresa'],['first_project','Primera app publicada'],['education','Estudios'],['project','Proyecto'],['fitness','Fitness']].map(([v,l])=>`<option value="${v}">${l}</option>`).join(''))+`<div class="field-row">${selectField('Precisión de fecha','precision',[['exact','Fecha exacta'],['month','Mes y año'],['year','Sólo año'],['unknown','No la recuerdo']].map(([v,l])=>`<option value="${v}">${l}</option>`).join(''))}${field('Fecha','date','date',localDay(),'required')}</div><div class="field"><label>Skills relacionadas</label><div class="skill-checks">${activeSkills().map(sk=>`<label><input type="checkbox" name="skillIds" value="${esc(sk.id)}" ${sk.id===skillId?'checked':''}>${esc(sk.icon)} ${esc(sk.name)}</label>`).join('')}</div></div>`+field('Evidencia opcional (URL)','evidence','url','','placeholder="https://…"')+`<p class="subtle" style="font-size:11px;margin-top:15px">Un hito conserva un resultado. No concede XP automáticamente.</p></details>`,'','Guardar hito');}
function onboarding(){openForm('Your story starts here.','Ponle nombre a tu personaje. Lo que ya has aprendido también cuenta.','onboarding',field('Tu nombre','name','text','','placeholder="¿Cómo te llamas?" maxlength="60" required')+`<div class="field-row">${field('Tu símbolo','avatar','text','✦','maxlength="12" required')}${selectField('Zona horaria','timezone',timezones().map(tz=>`<option>${esc(tz)}</option>`).join(''))}</div><div class="field"><label>Nivel inicial aproximado · opcional</label><small>Deja Level 1 para empezar de cero. El resto se guarda como XP histórica.</small></div><div class="onboarding-skills">${activeSkills().map(sk=>`<div class="baseline-row"><label for="base-${esc(sk.id)}">${esc(sk.icon)} ${esc(sk.name)}</label><input id="base-${esc(sk.id)}" name="base:${esc(sk.id)}" type="number" value="1" min="1" max="100" required aria-label="Nivel inicial de ${esc(sk.name)}"></div>`).join('')}</div>`,'','Empezar mi aventura');}
function editEventForm(id){const e=getState().events.find(e=>e.id===id);if(!e)return;openForm('Review activity.','Ajusta la sugerencia antes de confirmar.','event-edit',field('Actividad','title','text',e.title,'maxlength="180" required')+selectField('Skill','skillId',skillOptions(e.skillId))+`<div class="field-row">${field('XP sugerida','xp','number',e.xp,'min="0" max="1000000" step="1" required')}${field('Fecha y hora','occurredAt','datetime-local',datetimeInput(e.occurredAt),'required')}</div>`,id,'Guardar cambios');}
function download(text,name,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportBackup(){download(backup(),`HT-${isDemo()?'demo':'backup'}-${localDay()}.json`);toast('Copia exportada. Guárdala para conservar tu historia.');}
function filterEvents(){render();}
app.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='heat-range'){heatRange=Number(el.value);render();}else if(el.id==='heat-metric'){heatMetric=el.value;render();}else if(el.id.startsWith('filter-')){filters[el.id.slice(7)]=el.value;filterEvents();}else if(el.classList.contains('inbox-check')){el.checked?selected.add(el.value):selected.delete(el.value);render();}else if(el.id==='calendar-file'){const file=el.files[0];if(!file)return;if(file.size>5*1024*1024)throw new Error('El calendario debe ocupar menos de 5 MB.');const skillId=document.querySelector('#calendar-skill').value;const parsed=parseICS(await file.text(),getState().profile.timezone);let imported=0;await change(s=>{imported=importRecords(s,parsed.records,skillId);});toast(`${imported} eventos importados a Inbox`);toast(parsed.message);location.hash='/inbox';}else if(el.id==='restore-file'){const file=el.files[0];if(!file)return;if(file.size>10*1024*1024)throw new Error('La copia debe ocupar menos de 10 MB.');restoreData=D.validateState(JSON.parse(await file.text()));openForm('Restaurar tu historia.','La copia reemplazará el perfil actual de este navegador.','restore',`<p class="notice">${esc(restoreData.profile.name||'Perfil')} · ${restoreData.events.length} actividades · ${restoreData.skills.length} skills · ${restoreData.ledger.length} transacciones de XP</p><p class="subtle" style="font-size:12px">Antes de restaurar se descargará una copia de tu perfil actual. No se mezclan dos historiales.</p>`,'','Exportar actual y restaurar');}}catch(err){toast(err.message,'error');}});
// Search keeps focus and caret while updating results.
app.addEventListener('input',e=>{if(e.target.id==='filter-query'){const caret=e.target.selectionStart;filters.query=e.target.value;render();const el=document.querySelector('#filter-query');el.focus();el.setSelectionRange(caret,caret);}});
modal.addEventListener('change',e=>{if(e.target.name==='precision'){const el=modal.querySelector('[name="date"]'),v=e.target.value;el.type=v==='month'?'month':v==='year'?'number':'date';el.disabled=v==='unknown';el.required=v!=='unknown';el.value=v==='month'?localDay().slice(0,7):v==='year'?localDay().slice(0,4):localDay();if(v==='year'){el.min='1';el.max=localDay().slice(0,4);}else{el.removeAttribute('min');el.removeAttribute('max');}}if(e.target.name==='skillId'&&modal.querySelector('[name="questId"]')){const suggestionsEl=modal.querySelector('.capture-suggestions');if(suggestionsEl)suggestionsEl.innerHTML=captureSuggestions(e.target.value);const qel=modal.querySelector('[name="questId"]');qel.value='';for(const o of qel.options){const q=getState().quests.find(q=>q.id===o.value);o.disabled=!!q&&q.skillId!==e.target.value;}}});
async function action(el){const act=el.dataset.action,id=el.dataset.id;switch(act){case 'close':modal.close();return;case 'more':modalContent.innerHTML=`<div class="modal-header"><div><h2>Your journey</h2><p>Más vistas de tu progreso.</p></div><button class="icon-btn" data-action="close" aria-label="Cerrar">${icon('close',20)}</button></div><nav class="modal-body">${[['/activities','Historial'],['/achievements','Achievements'],['/review','Weekly Review'],['/profile','Profile'],['/settings','Settings']].map(([url,name])=>`<button class="btn btn-ghost" style="display:flex;width:100%;margin:8px 0" data-action="navigate" data-route="${url}">${name}</button>`).join('')}</nav>`;modal.showModal();return;case 'navigate':modal.close();location.hash=el.dataset.route;return;case 'quick-log':{const skillId=el.dataset.skill;if(busy||quickLocks.has(skillId))return;const sk=skBy(skillId);if(!sk)return;const [,title,xp]=quickFor(sk);quickLocks.add(skillId);el.disabled=true;try{const now=new Date().toISOString();await change(s=>D.createEvent(s,{title,skillId,xp,occurredAt:now},now),`${sk.icon} ${sk.name} · ${title} · +${xp} XP`);}finally{setTimeout(()=>{quickLocks.delete(skillId);const b=app.querySelector(`[data-action="quick-log"][data-skill="${CSS.escape(skillId)}"]`);if(b)b.disabled=false;},900);}return;}case 'activity':activityForm(el.dataset.skill);return;case 'capture-milestone':milestoneForm(modal.querySelector('[name=title]').value,modal.querySelector('[name=skillId]').value);return;case 'capture-preset':modal.querySelector('[name=title]').value=el.dataset.title;case 'xp-preset':modal.querySelector('[name=xp]').value=el.dataset.xp;modal.querySelectorAll('.effort-picker button').forEach(b=>b.classList.toggle('selected',b.dataset.xp===el.dataset.xp));return;case 'skill':skillForm(id);return;case 'quest':questForm();return;case 'milestone':milestoneForm();return;case 'baseline':baselineForm(id);return;case 'onboarding':onboarding();return;case 'profile-edit':location.hash='/settings';return;case 'demo':if(busy)return;toggleDemo();selected.clear();modal.close();render();toast(isDemo()?'Demo abierta. Tu perfil real sigue intacto.':'Has vuelto a tu perfil.');return;case 'export':exportBackup();return;case 'quest-tab':questTab=el.dataset.tab;render();return;case 'quest-abandon':await change(s=>D.abandonQuest(s,id),'Quest abandonada. Tu XP se conserva.');return;case 'event-confirm':await change(s=>D.confirmEvent(s,id),'Actividad confirmada.');selected.delete(id);render();return;case 'event-reject':await change(s=>D.rejectEvent(s,id),'Actividad descartada, sin XP.');selected.delete(id);render();return;case 'event-edit':editEventForm(id);return;case 'select-all':{const all=getState().events.filter(e=>e.status==='pending');selected.size===all.length?selected.clear():all.forEach(e=>selected.add(e.id));render();return;}case 'bulk-confirm':case 'bulk-reject':{const ids=[...selected];await change(s=>ids.forEach(id=>act==='bulk-confirm'?D.confirmEvent(s,id):D.rejectEvent(s,id)),`${ids.length} actividades ${act==='bulk-confirm'?'confirmadas':'descartadas'}.`);selected.clear();render();return;}case 'review-prev':reviewWeek=D.shiftDay(reviewWeek,-7);render();return;case 'review-next':if(reviewWeek<D.weekStart(localDay()))reviewWeek=D.shiftDay(reviewWeek,7);render();return;case 'heat-day':filters={skill:'',source:'',status:'confirmed',query:'',from:el.dataset.day,to:el.dataset.day,type:''};location.hash='/activities';return;}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){e.preventDefault();action(el).catch(()=>{});}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();const btn=form.querySelector('button[type="submit"]');if(btn?.disabled)return;const data=new FormData(form),v=Object.fromEntries(data.entries()),type=form.dataset.form,id=form.dataset.id;const err=form.querySelector('.form-error');if(err)err.textContent='';if(btn)btn.disabled=true;try{const now=new Date().toISOString();switch(type){case 'quick-start':activityForm(undefined,v.title);return;case 'activity':{if(v.questId&&getState().quests.find(q=>q.id===v.questId)?.skillId!==v.skillId)throw new Error('La quest debe pertenecer a la misma skill.');await change(s=>D.createEvent(s,{...v,occurredAt:v.occurredAt?zonedInput(v.occurredAt,s.profile.timezone):now,isHistorical:data.has('isHistorical')},now),'Actividad registrada. Un paso más.');break;}case 'skill':await change(s=>id?D.updateSkill(s,id,v):D.addSkill(s,v),id?'Skill actualizada.':'Nueva skill creada.');break;case 'baseline':await change(s=>D.baseline(s,v.skillId,Number(v.level),zonedInput(v.cutoff,s.profile.timezone),now),'Tu punto de partida está registrado.');break;case 'quest':await change(s=>D.createQuest(s,v,now),'Tu nueva quest está activa.');break;case 'quest-progress':await change(s=>D.questProgress(s,id,v.progress,now),'Progreso actualizado.');return;case 'milestone':await change(s=>D.addMilestone(s,{...v,skillIds:data.getAll('skillIds')},now),'Milestone conservado en tu historia.');break;case 'event-edit':await change(s=>D.editEvent(s,id,{...v,occurredAt:zonedInput(v.occurredAt,s.profile.timezone)},now),'Sugerencia actualizada.');break;case 'onboarding':await change(s=>{if(!v.name.trim())throw new Error('Introduce tu nombre.');s.profile.name=v.name.trim();s.profile.avatar=v.avatar.trim()||'✦';s.profile.timezone=v.timezone;s.profile.onboarded=true;for(const sk of s.skills){const l=Number(v['base:'+sk.id]);if(l>1&&!s.ledger.some(x=>x.skillId===sk.id))D.baseline(s,sk.id,l,now,now);}},'Bienvenido a tu propia aventura.');break;case 'reflection':await change(s=>{s.reflections[reviewWeek]={wentWell:String(v.wentWell).slice(0,10000),wentWrong:String(v.wentWrong).slice(0,10000),nextFocus:String(v.nextFocus).slice(0,10000),savedAt:now,summary:D.weeklySummary(s,reviewWeek)};},'Reflexión guardada.');return;case 'profile':await change(s=>{if(!v.name.trim()||!v.avatar.trim())throw new Error('Introduce un nombre y un símbolo.');s.profile.name=v.name.trim().slice(0,60);s.profile.avatar=v.avatar.trim().slice(0,12);new Intl.DateTimeFormat('es',{timeZone:v.timezone}).format();s.profile.timezone=v.timezone;s.profile.onboarded=true;},'Perfil actualizado.');return;case 'github':{btn.textContent='Importando…';const since=v.since+'T00:00:00Z';if(+new Date(since)>+new Date())throw new Error('La fecha de inicio no puede ser futura.');const res=await fetch(`/api/github?username=${encodeURIComponent(v.username)}&since=${encodeURIComponent(since)}`);const json=await res.json();if(!res.ok)throw new Error(json.error||'No se pudo consultar GitHub.');let added=0;await change(s=>{s.integrations.github=v.username;added=importRecords(s,json.records,v.skillId);s.integrations.lastGithubSync=now;});toast(`${added} actividades nuevas en Inbox.`);toast(json.message);location.hash='/inbox';return;}case 'restore':exportBackup();{const {unlocks}=await restore(restoreData);restoreData=null;render();toast('Backup restaurado.');}break;}
 modal.close();}catch(error){if(err)err.textContent=error.message;else toast(error.message,'error');}finally{if(btn?.isConnected){btn.disabled=false;if(type==='github')btn.textContent='Importar a Inbox';}}});
window.addEventListener('hashchange',()=>{selected.clear();render();window.scrollTo(0,0);});
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
try{load();render();observe(error=>error?toast(error.message,'error'):render());}catch(error){app.innerHTML=`<main style="padding:40px;max-width:650px"><h1>No se pudo abrir tu historia.</h1><p style="margin-top:15px">${esc(error.message)}. No se han borrado tus datos. Comprueba que el navegador permite almacenamiento local.</p></main>`;}
